  async revisions(): Promise<Response> {
    const { id } = this.validateParams(PostIdParamSchema)
    const post = await Post.findOrFail(id)
    await this.authorize('update', [Post, post])

    const revisions = await PostRevision.newQuery()
      .where('postId', post.id)
      .orderBy('id', 'desc')
      .get()

    return this.inertia(pages.posts.Revisions, {
      post: new PostResource(post).toJSON(),
      revisions: revisions.map((revision) => ({
        id: revision.id,
        title: revision.title,
        createdAt: revision.createdAt,
      })),
    })
  }

  async restore(): Promise<Response> {
    const { id, revisionId } = this.validateParams(PostRevisionParamSchema)
    const post = await Post.findOrFail(id)
    await this.authorize('update', [Post, post])

    const revision = await PostRevision.newQuery()
      .where('id', revisionId)
      .where('postId', post.id)
      .first()
    if (!revision) {
      return this.notFound()
    }

    // Restoring is an edit like any other: keep what is being replaced.
    await this.keepRevision(post)
    await Post.update(
      { id: post.id },
      { title: revision.title, excerpt: revision.excerpt, body: revision.body },
    )

    return this.redirect(`/posts/${post.id}`)
  }

  private async keepRevision(post: {
    id: number
    title: string
    excerpt: string
    body: string
  }): Promise<void> {
    await PostRevision.forceCreate({
      postId: post.id,
      title: post.title,
      excerpt: post.excerpt,
      body: post.body,
    })
  }
